"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
from pathlib import Path

def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir):
    """查找根目录下所有重复文件（按内容哈希）。返回字典 {hash: [path]}。"""
    root = Path(root_dir).resolve()
    hash_map = {}
    for path in root.rglob('*'):
        if path.is_file():
            file_hash = compute_hash(path)
            hash_map.setdefault(file_hash, []).append(str(path))
    return hash_map


def format_output(hash_map, dry_run=False):
    """格式化输出。dry_run=True 时只打印将要删除的路径列表（不实际操作）。"""
    if not hash_map:
        print('未发现重复文件')
        return
    lines = []
    for file_list in hash_map.values():
        if len(file_list) > 1:
            lines.append(f'重复组：{file_list}')
    print('\n'.join(lines))


def main(argv=None):
    """命令行入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='仅打印将要删除的路径，不实际操作')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出')
    args = parser.parse_args(argv)

    hash_map = find_duplicates(args.directory)
    if args.json:
        import json
        print(json.dumps({k: v for k, v in hash_map.items() if len(v) > 1}, indent=2))
    elif args.dry_run:
        format_output(hash_map, dry_run=True)
    else:
        format_output(hash_map, dry_run=False)


if __name__ == '__main__':
    main()

