"""清洗脚本：读取 UTF-8 文件并去除首尾空白与 BOM。"""
import os
from pathlib import Path

# 处理带 BOM 的 UTF-8 文件
class BOMHandler:
    def __init__(self, file_path):
        self.file_path = file_path

    def read_file(self):
        with open(file_path, 'rb') as f:
            raw_data = f.read()
        # 移除 UTF-8 BOM（EF BB BF）
        if raw_data.startswith(b'\xef\xbb\xbf'):
            raw_data = raw_data[3:]
        return raw_data.decode('utf-8')

    def clean_text(self, text):
        # 去除首尾空白字符（空格、换行、制表符等）
        cleaned = text.strip()
        # 处理可能存在的多行 BOM（跨文件情况）
        while '\ufeff' in cleaned:
            cleaned = cleaned.replace('\ufeff', '')
        return cleaned

# 主函数：读取并清洗指定路径的文件

def main(file_path):
    # 检查文件是否存在
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"文件不存在: {file_path}")

    handler = BOMHandler(file_path)
    raw_text = handler.read_file()
    cleaned_text = handler.clean_text(raw_text)
    return cleaned_text

