"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(file_path):
    """解析 JSON 日志文件，返回列表。"""
    logs = []
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            if line.strip():
                try:
                    log = json.loads(line)
                    logs.append(log)
                except json.JSONDecodeError:
                    continue
    return logs

def group_by_hour(logs):
    """按小时分组统计。"""
    groups = {}
    for log in logs:
        hour_key = datetime.fromisoformat(log['timestamp']).hour
        if hour_key not in groups:
            groups[hour_key] = {'count': 0, 'total_bytes': 0}
        groups[hour_key]['count'] += 1
        groups[hour_key]['total_bytes'] += log.get('size', 0)
    return groups

def write_csv(groups, file_path):
    """将分组结果写入 CSV。"""
    with open(file_path, 'w', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count', 'total_bytes'])
        for hour in sorted(groups.keys()):
            writer.writerow([hour, groups[hour]['count'], groups[hour]['total_bytes']])

