import os
from datetime import datetime, timezone

# 日志格式：<timestamp>"<level> <message>"
# 例如：2024-01-01T12:00:00+08:00 "INFO" "用户登录"
LOG_FORMAT = "<timestamp><\"level\"> <\"message\">"

class LogEntry:
    def __init__(self, timestamp_str, level, message):
        self.timestamp = datetime.fromisoformat(timestamp_str.replace("Z", "+00:00"))
        self.level = level
        self.message = message

    def to_dict(self):
        return {
            "timestamp": self.timestamp.isoformat(),
            "level": self.level,
            "message": self.message
        }

class LogAggregator:
    def __init__(self, output_dir="./logs"):
        os.makedirs(output_dir, exist_ok=True)
        self.output_file = os.path.join(output_dir, "aggregated.log")

    def add_entry(self, entry):
        with open(self.output_file, "a", encoding="utf-8") as f:
            f.write(entry.to_dict() + "\n")

    def filter_by_level(self, level):
        return [e for e in self._entries if e.level == level]

    def filter_by_time_window(self, start_dt, end_dt):
        return [e for e in self._entries if start_dt <= e.timestamp <= end_dt]

    def _entries(self):
        with open(self.output_file, "r", encoding="utf-8") as f:
            lines = f.readlines()
        entries = []
        for line in lines:
            if not line.strip():
                continue
            try:
                entry = LogEntry(*line.split(" ", 2))
            except Exception:
                continue
            entries.append(entry)
        return entries

    def get_filtered_entries(self, level=None, start_dt=None, end_dt=None):
        entries = self._entries()
        if level is not None:
            entries = [e for e in entries if e.level == level]
        if start_dt is not None:
            entries = [e for e in entries if start_dt <= e.timestamp]
        if end_dt is not None:
            entries = [e for e in entries if e.timestamp <= end_dt]
        return entries

