"""日志聚合脚本：读取多路日志文件，按时间戳排序后输出汇总。"""
import os
from datetime import datetime

def parse_line(line):
    """解析单行日志，返回 (timestamp, level, message)。"""
    parts = line.strip().split(' ')
    if len(parts) < 3:
        return None
    try:
        ts = datetime.strptime(parts[0], '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None
    level = parts[1]
    message = ' '.join(parts[2:])
    return (ts, level, message)

def read_file(path):
    """读取文件，返回所有解析后的日志。"""
    logs = []
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            result = parse_line(line)
            if result is not None:
                logs.append(result)
    return logs

def merge_logs(logs):
    """合并多路日志，按时间戳排序。"""
    sorted_logs = sorted(logs, key=lambda x: x[0])
    return sorted_logs

def main():
    """主入口：读取所有文件，合并排序并输出。"""
    files = [f for f in os.listdir('.') if f.endswith('.log')]
    all_logs = []
    for file_path in files:
        all_logs.extend(read_file(file_path))
    merged = merge_logs(all_logs)
    for ts, level, message in merged:
        print(f"{ts} {level}: {message}")

