import os
import shutil
from pathlib import Path


def merge_directories(dest, src):
    """Merge two directories into dest by moving files and removing empty dirs."""
    if not isinstance(dest, str) or not isinstance(src, str):
        raise TypeError("dest and src must be strings")

    dest_path = Path(dest)
    src_path = Path(src)

    # 1. Move files from src to dest
    for item in src_path.iterdir():
        if item.is_file():
            shutil.move(str(item), str(dest_path / item.name))
        elif item.is_dir():
            # Recursively merge subdirectories
            merge_directories(dest_path / item.name, item)

    # 2. Remove empty directories in dest
    for parent, dirs in os.walk(dest_path, topdown=False):
        for dir_name in dirs:
            dir_path = Path(parent) / dir_name
            try:
                if not any(Path(dir_path / f).is_file() for f in dir_path.iterdir()):
                    shutil.rmtree(str(dir_path))
            except FileNotFoundError:
                pass


