"""按文件大小分组后计算哈希，避免大文件全量读取。"""
import os
from collections import defaultdict

def group_by_size(file_paths):
    """按文件大小分组，返回 {size: [paths]} 的字典。"""
    groups = defaultdict(list)
    for path in file_paths:
        try:
            size = os.path.getsize(path)
        except OSError:
            continue
        groups[size].append(path)
    return dict(groups)


def hash_file_group(group):
    """对同一尺寸的文件组计算哈希，返回 {path: hash}。"""
    result = {}
    for path in group:
        try:
            h = _hash(path)
        except OSError:
            continue
        result[path] = h
    return result


def _hash(path):
    """计算单个文件的 SHA-256 哈希。"""
    import hashlib
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def main():
    """入口：读取目录下所有 .txt 文件，按大小分组后计算哈希。"""
    import sys
    root = sys.argv[1] if len(sys.argv) > 1 else '.'
    txt_files = []
    for dirpath, _, filenames in os.walk(root):
        for name in filenames:
            if name.endswith('.txt'):
                txt_files.append(os.path.join(dirpath, name))

    groups = group_by_size(txt_files)
    hashes = {}
    for size, paths in groups.items():
        hashes.update(hash_file_group(paths))

    print(f"共处理 {len(txt_files)} 个文件，{len(groups)} 组。")
    for path, h in sorted(hashes.items()):
        print(f"{path}: {h}")


